alter table private.case_videos add column paths text[] not null default '{}';
create function public.configure_case_video_paths(p_id uuid,p_hash text,p_paths text[]) returns boolean language plpgsql security definer set search_path='' as $$ begin
 if cardinality(p_paths) not between 1 and 10 or exists(select 1 from unnest(p_paths)p where p !~ ('^'||p_hash||'/'||p_id::text||'/[0-9]+\.enc$')) then raise exception 'Bounded scoped video paths required';end if;
 update private.case_videos set paths=p_paths where id=p_id and case_hash=p_hash and status='pending';return found;end $$;
revoke all on function public.configure_case_video_paths(uuid,text,text[]) from public,anon,authenticated;grant execute on function public.configure_case_video_paths(uuid,text,text[]) to service_role;
create or replace function public.case_videos(p_hash text) returns jsonb language sql stable security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'path',v.path,'paths',v.paths,'payload',v.payload,'status',v.status,'createdAt',v.created_at)),'[]'::jsonb) from private.case_videos v join private.private_cases c on c.token_hash=v.case_hash where c.token_hash=p_hash and c.revoked_at is null and c.expires_at>now(); $$;
create or replace function public.expired_case_files(p_limit integer default 100) returns jsonb language sql security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('hash',c.token_hash,'photos',(select coalesce(jsonb_agg(jsonb_build_object('original',m.original_path,'derivative',m.derivative_path)),'[]'::jsonb) from private.case_media m where m.case_hash=c.token_hash),'documents',(select coalesce(jsonb_agg(a.original_path),'[]'::jsonb) from private.case_attachments a where a.case_hash=c.token_hash),'videos',(select coalesce(jsonb_agg(chunk.object_path),'[]'::jsonb) from private.case_videos v cross join lateral unnest(v.paths) chunk(object_path) where v.case_hash=c.token_hash))),'[]'::jsonb) from(select token_hash from private.private_cases where expires_at<now() order by expires_at limit greatest(1,least(p_limit,100)))c;
$$;
create or replace function public.list_private_case_events(p_hash text) returns jsonb language sql security definer set search_path='' as $$ select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'type',e.event_type,'payload',e.encrypted_payload,'createdAt',e.happened_at,'verifiedBy',e.verified_by) order by e.happened_at,e.id),'[]'::jsonb) from private.case_events e join private.private_cases c on c.token_hash=e.case_hash where c.token_hash=p_hash and c.revoked_at is null and c.expires_at>now(); $$;
